<?php

declare(strict_types=1);

// config/reference.php is generated by Symfony on every cache warmup, so it is not checked.
$finder = (new PhpCsFixer\Finder())
    ->in([__DIR__.'/src', __DIR__.'/tests', __DIR__.'/config', __DIR__.'/migrations'])
    ->notPath('reference.php')
    ->append([__FILE__])
;

return (new PhpCsFixer\Config())
    // Needed only for "declare_strict_types", which the assignment requires in every file.
    ->setRiskyAllowed(true)
    ->setRules([
        '@Symfony' => true,
        'declare_strict_types' => true,
        // Compact PHPDoc: no extra column alignment.
        'phpdoc_align' => ['align' => 'left'],
        // Compact PHPDoc: @param, @return and @throws stay together, without blank lines between them.
        'phpdoc_separation' => [
            'groups' => [
                ['param', 'return', 'throws'],
                ['deprecated', 'link', 'see', 'since'],
                ['author', 'copyright', 'license'],
                ['category', 'package', 'subpackage'],
                ['property', 'property-read', 'property-write'],
            ],
        ],
    ])
    ->setFinder($finder)
;
